func syncManagedAndLegacyInjectWithLifecycle(
	cmd *cobra.Command,
	ws internal.Workspace,
	feature, featurePath, worktreeName, worktreePath string,
	target managedInjectTarget,
	lifecycle *internal.ManagedFeatureLifecycleLock,
	modeReservation *managedFeatureRenameReservation,
) error {
	present, err := internal.ManagedTemplateStatePresent(featurePath)
	if err != nil {
		return err
	}
	if !present {
		return internal.InjectFiles(featurePath, worktreePath, target.Value)
	}
	state, err := internal.LoadManagedTemplateState(featurePath)
	if err != nil {
		return err
	}
	if _, ok := state.Roles[string(internal.ManagedTemplateRoleWorktree)]; !ok {
		return internal.InjectFiles(featurePath, worktreePath, target.Value)
	}
	request := internal.ManagedTemplatePlanRequest{
		Workspace: ws, Feature: feature, FeaturePath: featurePath,
		Roles:               []internal.ManagedTemplateRole{internal.ManagedTemplateRoleWorktree},
		LinkMaterializeOnly: true, OnlyWorktree: worktreeName,
		InjectInto: target.Value, InjectIntoSet: target.Explicit,
	}
	plan, err := internal.PlanManagedTemplate(request)
	if err != nil {
		return err
	}
	if noop, err := verifiedManagedInjectNoop(plan, []managedInjectDestination{{path: worktreePath}}); err != nil {
		return err
	} else if noop {
		return nil
	}
	lifecycleByPath := map[string]*internal.ManagedFeatureLifecycleLock(nil)
	if lifecycle != nil {
		lifecycleByPath = map[string]*internal.ManagedFeatureLifecycleLock{
			featurePath: lifecycle,
		}
	}
	modeByPath := map[string]*managedFeatureRenameReservation(nil)
	if modeReservation != nil {
		modeByPath = map[string]*managedFeatureRenameReservation{
			featurePath: modeReservation,
		}
	}
	if err := executeManagedTemplatePlansWithReservations(
		cmd, []*internal.ManagedTemplatePlan{plan}, lifecycleByPath, modeByPath,
	); err != nil {
		return err
	}
	excluded, err := internal.ManagedTemplateOwnedWorktreePaths(featurePath)
	if err != nil {
		return err
	}
	return internal.InjectFilesExcluding(featurePath, worktreePath, "", excluded)
}

func syncManagedAndLegacyInjectAll(
	cmd *cobra.Command,
	ws internal.Workspace,
	feature, featurePath string,
	target managedInjectTarget,
) (int, error) {
	present, err := internal.ManagedTemplateStatePresent(featurePath)
	if err != nil {
		return 0, err
	}
	if !present {
		return internal.InjectFilesForFeature(featurePath, target.Value)
	}
	state, err := internal.LoadManagedTemplateState(featurePath)
	if err != nil {
		return 0, err
	}
	if _, ok := state.Roles[string(internal.ManagedTemplateRoleWorktree)]; !ok {
		return internal.InjectFilesForFeature(featurePath, target.Value)
	}
	request := internal.ManagedTemplatePlanRequest{
		Workspace: ws, Feature: feature, FeaturePath: featurePath,
		Roles:               []internal.ManagedTemplateRole{internal.ManagedTemplateRoleWorktree},
		LinkMaterializeOnly: true,
		InjectInto:          target.Value, InjectIntoSet: target.Explicit,
	}
	plan, err := internal.PlanManagedTemplate(request)
	if err != nil {
		return 0, err
	}
	initialTargets, err := internal.DiscoverInjectWorktrees(featurePath)
	if err != nil {
		return 0, err
	}
	destinations := make([]managedInjectDestination, 0, len(initialTargets))
	for _, target := range initialTargets {
		destinations = append(destinations, managedInjectDestination{path: target.Path})
	}
	if noop, err := verifiedManagedInjectNoop(plan, destinations); err != nil {
		return 0, err
	} else if noop {
		return len(initialTargets), nil
	}
	if err := executeManagedTemplatePlans(cmd, []*internal.ManagedTemplatePlan{plan}); err != nil {
		return 0, err
	}
	excluded, err := internal.ManagedTemplateOwnedWorktreePaths(featurePath)
	if err != nil {
		return 0, err
	}
	targets, err := internal.DiscoverInjectWorktrees(featurePath)
	if err != nil {
		return 0, err
	}
	var injectErrs []error
	for _, worktree := range targets {
		if err := internal.InjectFilesExcluding(featurePath, worktree.Path, "", excluded); err != nil {
			injectErrs = append(injectErrs, fmt.Errorf("%s: %w", worktree.Name, err))
		}
	}
	return len(targets), errors.Join(injectErrs...)
}

func featureExists(path string) (bool, error) {
	info, err := os.Lstat(path)
	if errors.Is(err, fs.ErrNotExist) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
		return false, fmt.Errorf("feature path %s is not a regular directory", path)
	}
	return true, nil
}

package cli

import (
	"bufio"
	"bytes"
	"crypto/sha256"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"sort"
	"strconv"
	"strings"
	"unicode"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

type managedTemplateCheckedWriter struct{ io.Writer }

func (writer managedTemplateCheckedWriter) Write(data []byte) (int, error) {
	n, err := writer.Writer.Write(data)
	if err == nil && n != len(data) {
		err = io.ErrShortWrite
	}
	return n, err
}

type managedTemplateEdits struct {
	accepted []*managedTemplateEditorScratch
}

func (edits *managedTemplateEdits) verify() error {
	for _, scratch := range edits.accepted {
		if err := scratch.verifyAll(); err != nil {
			return err
		}
	}
	return nil
}

func (edits *managedTemplateEdits) finish(success bool) error {
	var errs []error
	if success {
		if err := edits.verify(); err != nil {
			errs = append(errs, fmt.Errorf("managed template effects completed but staged edit verification failed: %w", err))
			success = false
		}
	}
	for _, scratch := range edits.accepted {
		retain := !success
		if success {
			if err := scratch.cleanup(); err != nil {
				retain = true
				errs = append(errs, fmt.Errorf("managed template effects completed but editor scratch cleanup failed: %w", err))
			}
		}
		if retain {
			errs = append(errs, fmt.Errorf("accepted staged edits retained at %q (rendered incoming reference: %q)",
				scratch.filePath("edit"), scratch.filePath("incoming")))
		}
		errs = append(errs, scratch.Close())
	}
	return errors.Join(errs...)
}

func confirmManagedTemplateChanges(cmd *cobra.Command, plans []*internal.ManagedTemplatePlan, flags managedTemplateFlags, edits *managedTemplateEdits) error {
	// Keep the reader across menus and removal consent. Never pass its buffered
	// confirmation bytes to an editor; the editor gets the original terminal.
	reader := bufio.NewReader(cmd.InOrStdin())
	if flags.resolveConflicts {
		for _, plan := range plans {
			if err := internal.PreflightManagedTemplateMutation(plan); err != nil {
				return fmt.Errorf("%s: %w", plan.Request.Feature, err)
			}
			if err := recheckManagedTemplateSessions(plan); err != nil {
				return fmt.Errorf("%s: %w", plan.Request.Feature, err)
			}
		}
		if err := resolveManagedTemplateConflicts(cmd, reader, plans, edits); err != nil {
			return err
		}
	}
	return confirmManagedTemplateRemovals(cmd, plans, flags.allowRemoval, reader)
}

func resolveManagedTemplateConflicts(cmd *cobra.Command, reader *bufio.Reader, plans []*internal.ManagedTemplatePlan, edits *managedTemplateEdits) error {
	sort.Slice(plans, func(i, j int) bool { return plans[i].Request.Feature < plans[j].Request.Feature })
	warned := false
	for _, plan := range plans {
		for _, conflict := range plan.PendingConflicts() {
			if !managedTemplateInputIsTTY(cmd.InOrStdin()) {
				return fmt.Errorf("feature %q role=%s path=%q: --resolve-conflicts requires terminal input for decisions; piped answers are not consent",
					conflict.Feature, conflict.Role, conflict.Path)
			}
			if !warned && plan.NewState.Version == 1 {
				if _, err := fmt.Fprintln(managedTemplateCheckedWriter{cmd.ErrOrStderr()},
					"Warning: keeping or editing a noncanonical customization upgrades ownership to v2. "+
						"Released v1.2.18-rc.5 refuses v2 in managed-state readers/writers and may also refuse workspace owner discovery. "+
						"This is not a universal disable switch: rc.5 checkout tws new may still create logical branch/stack metadata without reading the ledger, leaving template bytes and acknowledgements unchanged. "+
						"Use the newer CLI consistently in this workspace; no downgrade is provided."); err != nil {
					return err
				}
				warned = true
			}
			if err := resolveManagedTemplateConflict(cmd, reader, plans, plan, conflict, edits); err != nil {
				return err
			}
		}
	}
	return nil
}

func resolveManagedTemplateConflict(cmd *cobra.Command, reader *bufio.Reader, plans []*internal.ManagedTemplatePlan, plan *internal.ManagedTemplatePlan, conflict internal.ManagedTemplateConflict, edits *managedTemplateEdits) error {
	out := managedTemplateCheckedWriter{cmd.ErrOrStderr()}
	source := conflict.Source.Kind
	if conflict.Source.Kind == "registry" {
		source += ":" + conflict.Source.Scope + ":" + conflict.Source.Name + " origin=" + conflict.Source.OriginID
	}
	if _, err := fmt.Fprintf(out,
		"\nManaged text conflict: feature=%q role=%s path=%q\ndestination=%q\nsource=%q renderer=%q\ncurrent: sha256=%s mode=%04o\nincoming (rendered): sha256=%s mode=%04o\n",
		conflict.Feature, conflict.Role, conflict.Path, conflict.Destination, source, conflict.Agent,
		conflict.CurrentSHA256, conflict.CurrentMode, conflict.IncomingSHA256, conflict.IncomingMode); err != nil {
		return err
	}
	for {
		if _, err := fmt.Fprint(out, "keep / replace / diff / edit / cancel [k/r/d/e/C]: "); err != nil {
			return err
		}
		answer, err := readManagedTemplateAnswer(reader)
		if err != nil {
			return err
		}
		switch answer {
		case "", "c", "cancel":
			return errors.New("managed template update cancelled; no feature effects applied")
		case "k", "keep":
			return internal.ResolveManagedTemplateConflict(plan, conflict.Role, conflict.Path, "keep", nil)
		case "r", "replace":
			return internal.ResolveManagedTemplateConflict(plan, conflict.Role, conflict.Path, "replace", nil)
		case "d", "diff":
			if err := writeManagedTemplateDiff(out, "current/"+conflict.Destination, "incoming/"+conflict.Destination,
				conflict.CurrentContent(), conflict.IncomingContent()); err != nil {
				return err
			}
		case "e", "edit":
			data, accepted, err := editManagedTemplateConflict(cmd, reader, plans, conflict, edits)
			if err != nil {
				return err
			}
			if accepted {
				return internal.ResolveManagedTemplateConflict(plan, conflict.Role, conflict.Path, "edit", data)
			}
		default:
			if _, err := fmt.Fprintln(out, "Choose keep (k), replace (r), diff (d), edit (e), or cancel (c)."); err != nil {
				return err
			}
		}
	}
}

func readManagedTemplateAnswer(reader *bufio.Reader) (string, error) {
	answer, err := reader.ReadString('\n')
	if errors.Is(err, io.EOF) {
		return "", errors.New("managed template update cancelled: end of input before a complete answer")
	}
	if err != nil {
		return "", fmt.Errorf("reading managed template decision: %w", err)
	}
	if strings.ContainsRune(answer, '\x03') {
		return "", errors.New("managed template update cancelled: interrupted")
	}
	return strings.ToLower(strings.TrimSpace(answer)), nil
}

// A single contiguous unified hunk avoids invoking Git, pagers, diff drivers,
// external diff, or textconv. Unchanged interior lines may be repeated when
// there are several separated edits; the two byte snapshots remain exact.
func writeManagedTemplateDiff(out io.Writer, beforeLabel, afterLabel string, before, after []byte) error {
	out = managedTemplateCheckedWriter{out}
	if bytes.Equal(before, after) {
		_, err := fmt.Fprintln(out, "No content differences (compare the displayed permission modes).")
		return err
	}
	oldLines, newLines := managedTemplateDiffLines(before), managedTemplateDiffLines(after)
	prefix := 0
	for prefix < len(oldLines) && prefix < len(newLines) && bytes.Equal(oldLines[prefix], newLines[prefix]) {
		prefix++
	}
	oldEnd, newEnd := len(oldLines), len(newLines)
	for oldEnd > prefix && newEnd > prefix && bytes.Equal(oldLines[oldEnd-1], newLines[newEnd-1]) {
		oldEnd--
		newEnd--
	}
	start := max(0, prefix-3)
	oldLimit, newLimit := min(len(oldLines), oldEnd+3), min(len(newLines), newEnd+3)
	oldCount, newCount := oldLimit-start, newLimit-start
	oldStart, newStart := start+1, start+1
	if oldCount == 0 {
		oldStart = start
	}
	if newCount == 0 {
		newStart = start
	}
	if _, err := fmt.Fprintf(out, "--- %s\n+++ %s\n@@ -%d,%d +%d,%d @@\n",
		strconv.QuoteToASCII(beforeLabel), strconv.QuoteToASCII(afterLabel),
		oldStart, oldCount, newStart, newCount); err != nil {
		return err
	}
	writeLine := func(prefix byte, line []byte) error {
		if _, err := fmt.Fprintf(out, "%c%s", prefix, escapeManagedTemplateTerminal(string(line))); err != nil {
			return err
		}
		if !bytes.HasSuffix(line, []byte("\n")) {
			_, err := fmt.Fprintln(out, "\n\\ No newline at end of file")
			return err
		}
		return nil
	}
	for _, line := range oldLines[start:prefix] {
		if err := writeLine(' ', line); err != nil {
			return err
		}
	}
	for _, line := range oldLines[prefix:oldEnd] {
		if err := writeLine('-', line); err != nil {
			return err
		}
	}
	for _, line := range newLines[prefix:newEnd] {
		if err := writeLine('+', line); err != nil {
			return err
		}
	}
	for _, line := range oldLines[oldEnd:oldLimit] {
		if err := writeLine(' ', line); err != nil {
			return err
		}
	}
	return nil
}

func managedTemplateDiffLines(data []byte) [][]byte {
	if len(data) == 0 {
		return nil
	}
	lines := bytes.SplitAfter(data, []byte("\n"))
	if len(lines[len(lines)-1]) == 0 {
		lines = lines[:len(lines)-1]
	}
	return lines
}

func escapeManagedTemplateTerminal(text string) string {
	var safe strings.Builder
	for _, char := range text {
		if char != '\n' && char != '\t' && (!unicode.IsPrint(char) || unicode.Is(unicode.Cf, char)) {
			quoted := strconv.QuoteRuneToASCII(char)
			safe.WriteString(quoted[1 : len(quoted)-1])
		} else {
			safe.WriteRune(char)
		}
	}
	return safe.String()
}

func managedTemplateEditorCommand() string {
	for _, name := range []string{"VISUAL", "EDITOR"} {
		if command := strings.TrimSpace(os.Getenv(name)); command != "" {
			return command
		}
	}
	return "vi"
}

func parseManagedTemplateEditor(command string) ([]string, error) {
	var args []string
	var word strings.Builder
	var quote rune
	escaped, started := false, false
	for _, char := range command {
		switch {
		case escaped:
			word.WriteRune(char)
			escaped, started = false, true
		case char == '\\' && quote != '\'':
			escaped, started = true, true
		case quote != 0:
			if char == quote {
				quote = 0
			} else {
				word.WriteRune(char)
			}
		case char == '\'' || char == '"':
			quote, started = char, true
		case unicode.IsSpace(char):
			if started {
				args = append(args, word.String())
				word.Reset()
				started = false
			}
		default:
			word.WriteRune(char)
			started = true
		}
	}
	if quote != 0 || escaped {
		return nil, errors.New("malformed editor command: unmatched quote or trailing escape; use quoted argv, not shell syntax")
	}
	if started {
		args = append(args, word.String())
	}
	if len(args) == 0 || args[0] == "" {
		return nil, errors.New("editor command has no executable")
	}
	return args, nil
}

// Tests replace only the runner, never a user's editor or shell configuration.
var managedTemplateRunEditor = func(command *exec.Cmd) error { return command.Run() }

func editManagedTemplateConflict(cmd *cobra.Command, reader *bufio.Reader, plans []*internal.ManagedTemplatePlan, conflict internal.ManagedTemplateConflict, edits *managedTemplateEdits) (data []byte, accepted bool, retErr error) {
	out := managedTemplateCheckedWriter{cmd.ErrOrStderr()}
	args, err := parseManagedTemplateEditor(managedTemplateEditorCommand())
	if err != nil {
		return nil, false, err
	}
	scratch, err := newManagedTemplateEditorScratch(plans, conflict.CurrentContent(), conflict.IncomingContent())
	if err != nil {
		return nil, false, err
	}
	heldForInvocation := false
	defer func() {
		if !heldForInvocation {
			retErr = errors.Join(retErr, scratch.Close())
		}
	}()
	retain := func(cause error) ([]byte, bool, error) {
		return nil, false, fmt.Errorf("%w; staged edits retained at %q (rendered incoming reference: %q); no feature effects applied",
			cause, scratch.filePath("edit"), scratch.filePath("incoming"))
	}
	if _, err := fmt.Fprintf(out,
		"Two-way editing starts from current content at %q.\nRendered incoming reference: %q\nEditor must wait for completion (for example: code --wait). Exiting the editor does not accept its output.\n",
		scratch.filePath("edit"), scratch.filePath("incoming")); err != nil {
		return retain(err)
	}
	command := exec.CommandContext(cmd.Context(), args[0], append(args[1:], scratch.filePath("edit"))...)
	command.Stdin, command.Stdout, command.Stderr = cmd.InOrStdin(), cmd.OutOrStdout(), cmd.ErrOrStderr()
	if err := scratch.validateDirectories(); err != nil {
		return retain(err)
	}
	if err := managedTemplateRunEditor(command); err != nil {
		return retain(fmt.Errorf("editor failed: %w", err))
	}
	candidate, err := scratch.readCandidate()
	if err != nil {
		return retain(err)
	}
	if err := internal.ValidateManagedTemplateConflictContent(conflict, candidate); err != nil {
		return retain(err)
	}
	if err := writeManagedTemplateDiff(out, "current/"+conflict.Destination, "edited/"+conflict.Destination,
		conflict.CurrentContent(), candidate); err != nil {
		return retain(err)
	}
	if _, err := fmt.Fprintf(out, "Candidate sha256=%x mode=%04o\nAccept these exact edited bytes? [y/N] ",
		sha256.Sum256(candidate), conflict.IncomingMode); err != nil {
		return retain(err)
	}
	answer, err := readManagedTemplateAnswer(reader)
	if err != nil {
		return retain(err)
	}
	accepted = answer == "y" || answer == "yes"
	if accepted {
		edits.accepted = append(edits.accepted, scratch)
		heldForInvocation = true
		return candidate, true, nil
	}
	if _, err := fmt.Fprintf(out, "Discarding unaccepted staged edit at %q; returning to the conflict menu.\n", scratch.filePath("edit")); err != nil {
		return retain(err)
	}
	if err := scratch.cleanup(); err != nil {
		return retain(err)
	}
	return candidate, accepted, nil
}

//go:build !windows

package cli

import (
	"crypto/rand"
	"crypto/sha256"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"syscall"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"golang.org/x/sys/unix"
)

func managedTemplateTerminalInput(input io.Reader) bool {
	file, ok := input.(*os.File)
	if !ok {
		return false
	}
	_, err := unix.IoctlGetWinsize(int(file.Fd()), unix.TIOCGWINSZ)
	return err == nil
}

type managedEditorSnapshot struct {
	info fs.FileInfo
	hash [32]byte
}

type managedEditorDirectory struct {
	path string
	info fs.FileInfo
}

type managedTemplateEditorScratch struct {
	path    string
	name    string
	base    *os.Root
	root    *os.Root
	dir     *os.File
	parents []managedEditorDirectory
	files   map[string]managedEditorSnapshot
}

func newManagedTemplateEditorScratch(plans []*internal.ManagedTemplatePlan, current, incoming []byte) (*managedTemplateEditorScratch, error) {
	basePath, err := canonicalManagedEditorPath(os.TempDir())
	if err != nil {
		return nil, err
	}
	globalRegistry, err := internal.GlobalTemplateRegistryRoot()
	if err != nil {
		return nil, err
	}
	roots := []string{globalRegistry}
	for _, plan := range plans {
		roots = append(roots, plan.Request.FeaturePath, plan.Request.Workspace.MetadataRoot, plan.Request.Workspace.RepoRoot)
		for _, evidence := range plan.SourceEvidence {
			roots = append(roots, filepath.Dir(evidence.Path))
		}
	}
	parents, err := managedEditorDirectoryChain(basePath)
	if err != nil {
		return nil, err
	}
	if err := validateManagedEditorScratchRoots(basePath, parents, roots); err != nil {
		return nil, err
	}
	base, err := os.OpenRoot(basePath)
	if err != nil {
		return nil, err
	}
	opened, err := base.Open(".")
	if err != nil {
		_ = base.Close()
		return nil, err
	}
	baseInfo, statErr := opened.Stat()
	if err := errors.Join(statErr, opened.Close()); err != nil {
		_ = base.Close()
		return nil, err
	}
	if !os.SameFile(baseInfo, parents[0].info) {
		_ = base.Close()
		return nil, errors.New("editor scratch parent changed while opening")
	}
	if err := validateManagedEditorParents(parents); err != nil {
		_ = base.Close()
		return nil, err
	}
	if err := validateManagedEditorScratchRoots(basePath, parents, roots); err != nil {
		_ = base.Close()
		return nil, err
	}
	name := "tws-template-edit-" + rand.Text()
	if err := base.Mkdir(name, 0o700); err != nil {
		_ = base.Close()
		return nil, err
	}
	path := filepath.Join(basePath, name)
	root, err := base.OpenRoot(name)
	if err != nil {
		_ = base.Close()
		return nil, fmt.Errorf("opening private editor directory %q: %w", path, err)
	}
	dir, err := root.Open(".")
	if err != nil {
		_ = root.Close()
		_ = base.Close()
		return nil, fmt.Errorf("opening private editor directory %q: %w", path, err)
	}
	scratch := &managedTemplateEditorScratch{
		path: path, name: name, base: base, root: root, dir: dir, parents: parents,
		files: make(map[string]managedEditorSnapshot),
	}
	fail := func(cause error) (*managedTemplateEditorScratch, error) {
		return nil, errors.Join(fmt.Errorf("%w; editor scratch retained at %q", cause, path), scratch.Close())
	}
	if err := scratch.validateDirectories(); err != nil {
		return fail(err)
	}
	for _, file := range []struct {
		name string
		data []byte
	}{{"current", current}, {"incoming", incoming}, {"edit", current}} {
		if err := scratch.writePrivate(file.name, file.data); err != nil {
			return fail(err)
		}
	}
	return scratch, nil
}

func validateManagedEditorScratchRoots(basePath string, parents []managedEditorDirectory, roots []string) error {
	for _, protected := range roots {
		root, err := canonicalManagedEditorPath(protected)
		if err != nil {
			return err
		}
		outsideError := fmt.Errorf("editor scratch must be outside feature, worktree, and registry roots; choose a safe TMPDIR outside %q", protected)
		relative, err := filepath.Rel(root, basePath)
		if err != nil {
			return err
		}
		if relative == "." || (relative != ".." && !strings.HasPrefix(relative, ".."+string(filepath.Separator))) {
			return outsideError
		}
		info, err := os.Lstat(root)
		if errors.Is(err, fs.ErrNotExist) {
			continue
		}
		if err != nil {
			return fmt.Errorf("inspecting protected editor root %q: %w", protected, err)
		}
		if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
			return fmt.Errorf("protected editor root %q must be a regular directory", protected)
		}
		// EvalSymlinks does not normalize filesystem case or Unicode aliases.
		// Compare every physical ancestor, including the scratch base itself.
		for _, parent := range parents {
			if os.SameFile(info, parent.info) {
				return outsideError
			}
		}
	}
	return nil
}

func canonicalManagedEditorPath(path string) (string, error) {
	absolute, err := filepath.Abs(path)
	if err != nil {
		return "", err
	}
	resolved, err := filepath.EvalSymlinks(absolute)
	if err == nil {
		return resolved, nil
	}
	if !errors.Is(err, fs.ErrNotExist) {
		return "", err
	}
	parent := filepath.Dir(absolute)
	if parent == absolute {
		return "", err
	}
	resolvedParent, err := canonicalManagedEditorPath(parent)
	if err != nil {
		return "", err
	}
	return filepath.Join(resolvedParent, filepath.Base(absolute)), nil
}

func managedEditorDirectoryChain(path string) ([]managedEditorDirectory, error) {
	var directories []managedEditorDirectory
	for {
		info, err := os.Lstat(path)
		if err != nil {
			return nil, err
		}
		if !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
			return nil, fmt.Errorf("unsafe editor scratch parent %q", path)
		}
		directories = append(directories, managedEditorDirectory{path: path, info: info})
		parent := filepath.Dir(path)
		if parent == path {
			return directories, nil
		}
		path = parent
	}
}

func (scratch *managedTemplateEditorScratch) filePath(name string) string {
	return filepath.Join(scratch.path, name)
}

func (scratch *managedTemplateEditorScratch) validateDirectories() error {
	if err := validateManagedEditorParents(scratch.parents); err != nil {
		return err
	}
	held, err := scratch.dir.Stat()
	if err != nil {
		return err
	}
	current, err := scratch.base.Lstat(scratch.name)
	if err != nil {
		return err
	}
	if current.Mode()&os.ModeSymlink != 0 || !current.IsDir() ||
		current.Mode() != fs.ModeDir|0o700 || !os.SameFile(held, current) {
		return fmt.Errorf("private editor directory identity or permissions changed at %q", scratch.path)
	}
	return nil
}

func validateManagedEditorParents(parents []managedEditorDirectory) error {
	for _, parent := range parents {
		info, err := os.Lstat(parent.path)
		if err != nil {
			return err
		}
		if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() || !os.SameFile(info, parent.info) {
			return fmt.Errorf("editor scratch parent identity changed at %q", parent.path)
		}
	}
	return nil
}

func (scratch *managedTemplateEditorScratch) writePrivate(name string, data []byte) error {
	file, err := scratch.root.OpenFile(name, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return err
	}
	_, writeErr := file.Write(data)
	if err := errors.Join(writeErr, file.Chmod(0o600), file.Sync(), file.Close()); err != nil {
		return err
	}
	_, snapshot, err := scratch.readPrivate(name)
	if err != nil {
		return err
	}
	scratch.files[name] = snapshot
	return nil
}

func managedEditorPrivateFile(info fs.FileInfo) bool {
	stat, ok := info.Sys().(*syscall.Stat_t)
	return ok && info.Mode() == 0o600 && stat.Nlink == 1
}

func (scratch *managedTemplateEditorScratch) readPrivate(name string) ([]byte, managedEditorSnapshot, error) {
	if err := scratch.validateDirectories(); err != nil {
		return nil, managedEditorSnapshot{}, err
	}
	// O_NONBLOCK also prevents a swapped FIFO from hanging before fstat.
	fd, err := unix.Openat(int(scratch.dir.Fd()), name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, managedEditorSnapshot{}, fmt.Errorf("opening staged editor file %q without following links: %w", scratch.filePath(name), err)
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close() //nolint:errcheck
	before, err := file.Stat()
	if err != nil {
		return nil, managedEditorSnapshot{}, err
	}
	if !managedEditorPrivateFile(before) {
		return nil, managedEditorSnapshot{}, fmt.Errorf("staged editor file %q must be regular, private (0600), and not hard-linked", scratch.filePath(name))
	}
	data, err := io.ReadAll(file)
	if err != nil {
		return nil, managedEditorSnapshot{}, err
	}
	after, err := file.Stat()
	if err != nil {
		return nil, managedEditorSnapshot{}, err
	}
	pathInfo, err := scratch.root.Lstat(name)
	if err != nil {
		return nil, managedEditorSnapshot{}, err
	}
	if !managedEditorPrivateFile(after) || !managedEditorPrivateFile(pathInfo) ||
		!os.SameFile(before, after) || !os.SameFile(after, pathInfo) ||
		before.Size() != after.Size() || !before.ModTime().Equal(after.ModTime()) {
		return nil, managedEditorSnapshot{}, fmt.Errorf("staged editor file %q changed while being read", scratch.filePath(name))
	}
	if err := scratch.validateDirectories(); err != nil {
		return nil, managedEditorSnapshot{}, err
	}
	return data, managedEditorSnapshot{info: after, hash: sha256.Sum256(data)}, nil
}

func (scratch *managedTemplateEditorScratch) verifySnapshot(name string, expected managedEditorSnapshot) error {
	_, current, err := scratch.readPrivate(name)
	if err != nil {
		return err
	}
	if !os.SameFile(expected.info, current.info) || current.hash != expected.hash {
		return fmt.Errorf("staged editor reference or accepted output changed at %q", scratch.filePath(name))
	}
	return nil
}

func (scratch *managedTemplateEditorScratch) readCandidate() ([]byte, error) {
	for _, name := range []string{"current", "incoming"} {
		if err := scratch.verifySnapshot(name, scratch.files[name]); err != nil {
			return nil, err
		}
	}
	data, snapshot, err := scratch.readPrivate("edit")
	if err != nil {
		return nil, err
	}
	scratch.files["edit"] = snapshot
	return data, nil
}

func (scratch *managedTemplateEditorScratch) verifyAll() error {
	if err := scratch.validateDirectories(); err != nil {
		return err
	}
	entries, err := fs.ReadDir(scratch.root.FS(), ".")
	if err != nil {
		return err
	}
	for _, entry := range entries {
		if _, known := scratch.files[entry.Name()]; !known {
			return fmt.Errorf("unexpected editor residue at %q prevents automatic cleanup", scratch.filePath(entry.Name()))
		}
	}
	for name, expected := range scratch.files {
		if err := scratch.verifySnapshot(name, expected); err != nil {
			return err
		}
	}
	return nil
}

func (scratch *managedTemplateEditorScratch) cleanup() error {
	if err := scratch.verifyAll(); err != nil {
		return err
	}
	names := make([]string, 0, len(scratch.files))
	for name := range scratch.files {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		if err := scratch.verifySnapshot(name, scratch.files[name]); err != nil {
			return err
		}
		if err := scratch.root.Remove(name); err != nil {
			return err
		}
	}
	if err := scratch.validateDirectories(); err != nil {
		return err
	}
	return scratch.base.Remove(scratch.name)
}

func (scratch *managedTemplateEditorScratch) Close() error {
	return errors.Join(scratch.dir.Close(), scratch.root.Close(), scratch.base.Close())
}

