				evidenceBefore, err := os.ReadFile(reservationEvidence)
				if err != nil {
					t.Fatal(err)
				}
				var commandErr error
				if operation == "rename" {
					_, _, commandErr = runManagedCobra(t, renameCmd(), []string{
						"branch", feature, "entry", "renamed",
