		t.Fatal(err)
	}
	legacySentinel := filepath.Join(f.ws.FeaturePath("legacy"), "inject", "user.md")
	if err := os.WriteFile(legacySentinel, []byte("user\n"), 0o644); err != nil {
		t.Fatal(err)
	}
